import{_ as e,o as a,c as t,ae as n}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"","description":"File based routing is the simplest way to do routing in Fresh apps. Additionally custom patterns can be configured per route.\\n","frontmatter":{"description":"File based routing is the simplest way to do routing in Fresh apps. Additionally custom patterns can be configured per route.\\n"},"headers":[],"relativePath":"zh/1.x/concepts/routing.md","filePath":"zh/1.x/concepts/routing.md"}'),o={name:"zh/1.x/concepts/routing.md"};function i(p,s,l,d,r,c){return a(),t("div",null,[...s[0]||(s[0]=[n(`<p>Routing is the mechanism that determines what route a given incoming request is handled by. Fresh routes requests based on their URL path. By default routes specify which paths they are invoked for using the name of the file. Routes can also define a custom <a href="https://developer.mozilla.org/en-US/docs/Web/API/URL_Pattern_API" target="_blank" rel="noreferrer">URL pattern</a> to match against for more advanced use cases.</p><p>The file based routing in Fresh is very similar to the file based routing seen in other frameworks, namely Next.js. File names are used to determine which route a given request should be handled by. The pattern is determined based on the path of the file on disk, relative to the <code>routes/</code> directory.</p><p>File names are mapped to route patterns as follows:</p><ul><li>File extensions are ignored.</li><li>Literals in the file path are treated as string literals to match.</li><li>Files named <code>&lt;path&gt;/index.&lt;ext&gt;</code> behave identically to a file named <code>&lt;path&gt;.&lt;ext&gt;</code>.</li><li>Path segments can be made dynamic by surrounding an identifier with <code>[</code> and <code>]</code>.</li><li>Paths where the last path segment follows the structure <code>[...&lt;ident&gt;]</code> are treated as having a wildcard suffix.</li></ul><p>Here is a table of file names, which route patterns they map to, and which paths they might match:</p><table tabindex="0"><thead><tr><th>File name</th><th>Route pattern</th><th>Matching paths</th></tr></thead><tbody><tr><td><code>index.ts</code></td><td><code>/</code></td><td><code>/</code></td></tr><tr><td><code>about.ts</code></td><td><code>/about</code></td><td><code>/about</code></td></tr><tr><td><code>blog/index.ts</code></td><td><code>/blog</code></td><td><code>/blog</code></td></tr><tr><td><code>blog/[slug].ts</code></td><td><code>/blog/:slug</code></td><td><code>/blog/foo</code>, <code>/blog/bar</code></td></tr><tr><td><code>blog/[slug]/comments.ts</code></td><td><code>/blog/:slug/comments</code></td><td><code>/blog/foo/comments</code></td></tr><tr><td><code>old/[...path].ts</code></td><td><code>/old/:path*</code></td><td><code>/old/foo</code>, <code>/old/bar/baz</code></td></tr><tr><td><code>docs/[[version]]/index.ts</code></td><td><code>/docs{/:version}?</code></td><td><code>/docs</code>, <code>/docs/latest</code>, <code>/docs/canary</code></td></tr></tbody></table><p>Advanced use-cases can require that a more complex pattern be used for matching. A custom <a href="https://developer.mozilla.org/en-US/docs/Web/API/URL_Pattern_API" target="_blank" rel="noreferrer">URL pattern</a> can be specified in the route configuration. This pattern will be used instead of the file path based pattern:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { RouteConfig } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$fresh/server.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> config</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RouteConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  routeOverride: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/x/:module@:version/:path*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ...</span></span></code></pre></div><h2 id="route-groups" tabindex="-1">Route Groups <a class="header-anchor" href="#route-groups" aria-label="Permalink to &quot;Route Groups&quot;">​</a></h2><p>When working with <a href="/docs/1.x/concepts/layouts.html">layouts</a> or <a href="/docs/1.x/concepts/middleware.html">middlewares</a>, you&#39;ll sometimes come across a situation where you want your routes to inherit from a layout other than what&#39;s suggested by the URL segment.</p><p>Let&#39;s illustrate that with an example:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/about -&gt; layout A</span></span>
<span class="line"><span>/career -&gt; layout A</span></span>
<span class="line"><span>/archive -&gt; layout B</span></span>
<span class="line"><span>/contact -&gt; layout B</span></span></code></pre></div><p>Without any way to group routes this is a problem because every route segment can only have one <code>_layout</code> file.</p><div class="language-txt-files vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt-files</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;project root&gt;</span></span>
<span class="line"><span>└── routes</span></span>
<span class="line"><span>    ├── _layout.tsx  # applies to all routes here :(</span></span>
<span class="line"><span>    ├── about.tsx</span></span>
<span class="line"><span>    ├── career.tsx</span></span>
<span class="line"><span>    ├── archive.tsx</span></span>
<span class="line"><span>    └── contact.tsx</span></span></code></pre></div><p>We can solve this problem with route groups. A route group is a folder which has a name that is wrapped in parentheses. For example <code>(info)</code> would be considered a route group and so would <code>(marketing)</code>. This enables us to group related routes in a folder and use a different <code>_layout</code> file for each group.</p><div class="language-txt-files vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt-files</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>└── &lt;root&gt;/routes</span></span>
<span class="line"><span>    ├── (marketing)</span></span>
<span class="line"><span>    │   ├── _layout.tsx  # only applies to about.tsx and career.tsx</span></span>
<span class="line"><span>    │   ├── about.tsx</span></span>
<span class="line"><span>    │   └── career.tsx</span></span>
<span class="line"><span>    └── (info)</span></span>
<span class="line"><span>        ├── _layout.tsx  # only applies to archive.tsx and contact.tsx</span></span>
<span class="line"><span>        ├── archive.tsx</span></span>
<span class="line"><span>        └── contact.tsx</span></span></code></pre></div><blockquote><p>[warn]: Be careful about routes in different groups which match to the same URL. Such scenarios will lead to ambiguity as to which route file should be picked.</p><div class="language-txt-files vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt-files</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>└── &lt;root&gt;/routes</span></span>
<span class="line"><span>    ├── (group-1)</span></span>
<span class="line"><span>    │   └── about.tsx  # Bad: Maps to same \`/about\` url</span></span>
<span class="line"><span>    └── (group-2)</span></span>
<span class="line"><span>        └── about.tsx  # Bad: Maps to same \`/about\` url</span></span></code></pre></div></blockquote><h2 id="co-location" tabindex="-1">Co-location <a class="header-anchor" href="#co-location" aria-label="Permalink to &quot;Co-location&quot;">​</a></h2><p>If you want to store components and islands closer to their routes, you may want to use co-location.</p><p>When the name of a route group folder starts with an underscore, like <code>(_components)</code>, Fresh will ignore that folder and it’s effectively treated as private. This means you can use these private route folders to store components related to a particular route.</p><p>Following the above example, say you have some components you only want to use in your marketing pages, you could create a route group folder <code>(_components)</code> to house these.</p><p>The one special name is <code>(_islands)</code> which tells Fresh to treat all files in that folder as an island.</p><div class="language-txt-files vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt-files</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>└── &lt;root&gt;/routes</span></span>
<span class="line"><span>    ├── (marketing)</span></span>
<span class="line"><span>    │   ├── _layout.tsx</span></span>
<span class="line"><span>    │   ├── about.tsx</span></span>
<span class="line"><span>    │   ├── career.tsx</span></span>
<span class="line"><span>    │   ├── (_components)</span></span>
<span class="line"><span>    │   │   └── newsletter-cta.tsx</span></span>
<span class="line"><span>    │   └── (_islands)</span></span>
<span class="line"><span>    │       └── interactive-stats.tsx # Fresh treats this as an island</span></span>
<span class="line"><span>    └── shop</span></span>
<span class="line"><span>        ├── (_components)</span></span>
<span class="line"><span>        │   └── product-card.tsx</span></span>
<span class="line"><span>        └── (_islands)</span></span>
<span class="line"><span>            └── cart.tsx # Fresh treats this as an island</span></span></code></pre></div><p>Combined together, this gives you the ability to organise your code on a feature basis and put all related components, islands or anything else into a shared folder.</p>`,24)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
